function pickValue(resp) {
  try {
    const result = resp?.data?.result || [];
    if (!result.length) return 0;
    return Number(result[0].value?.[1] ?? 0);
  } catch {
    return 0;
  }
}

function extractLogLines(lokiResp) {
  const out = [];
  try {
    const streams = lokiResp?.data?.result || [];
    for (const s of streams) {
      const values = s?.values || [];
      for (const v of values) {
        out.push(String(v[1] ?? ""));
      }
    }
  } catch {}
  return out;
}

const correlation_id = (globalThis.crypto && globalThis.crypto.randomUUID) ? globalThis.crypto.randomUUID() : String(Date.now());

const errorRate = pickValue($node["Prometheus - Error Rate"].json);
const latencyMs = pickValue($node["Prometheus - Latency P95"].json);
const dbUtil = pickValue($node["Prometheus - DB Util"].json);

const logLines = extractLogLines($node["Loki - Recent Errors"].json);
const logText = logLines.join('
');

let severity = 'P3';
if (errorRate > 50 || latencyMs > 1000) severity = 'P1';
else if (errorRate >= 20 && errorRate <= 50) severity = 'P2';

let probable_root_cause = 'Elevated errors detected; collect more telemetry.';
let recommended_actions = 'Monitor and assign an owner to investigate.';

const crashLike = /panic|crash|segfault|killed|oom|rollback|deployment/i.test(logText);

if (dbUtil >= 85) {
  probable_root_cause = 'Database connection pool saturation';
  recommended_actions = 'Increase pool size; recycle connections; consider read replicas.';
} else if (latencyMs > 1000 && dbUtil < 60) {
  probable_root_cause = 'Downstream dependency slowdown';
  recommended_actions = 'Enable circuit breaker; increase timeouts; check downstream health.';
} else if (errorRate > 20 && crashLike) {
  probable_root_cause = 'Application crash or deployment failure';
  recommended_actions = 'Rollback deployment; restart service; review recent changes.';
}

return [{
  json: {
    correlation_id,
    timestamp: new Date().toISOString(),
    service_name: 'payment-service',
    severity,
    error_rate_percent: Number(errorRate.toFixed(2)),
    latency_ms: Number(latencyMs.toFixed(0)),
    db_pool_utilization: Number(dbUtil.toFixed(0)),
    probable_root_cause,
    recommended_actions,
    logs: logLines.slice(0, 10)
  }
}];
